<script setup>
import { computed, nextTick, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import { statusPillClass } from '../data/stockOutMotorStatus'
import { refreshCsrfToken } from '../data/session'
import { currentUser, loadMyRoles } from '../data/user'
import { notifyError, notifySuccess } from '../composables/toast'
import SelectMenu from '../components/SelectMenu.vue'
import StockOutUnitCards from '../components/StockOutUnitCards.vue'

const DOCTYPE = 'Stock Out Motor'
const route = useRoute()
const name = computed(() => route.params.name)
const displayTitle = computed(() => doc.data?.name || name.value)

// Child table "List Unit" (Stock Out Motor Item) dirender sebagai kartu
// collapsible via StockOutUnitCards; di sini hanya perlu hitung jumlah barisnya.
function tableRows(fieldname) {
	const src = doc.data?.[fieldname]
	return Array.isArray(src) ? src : []
}

// Textarea auto-tinggi.
const AUTOGROW_MAX = 180
function fitTextarea(el) {
	if (!el) return
	el.style.height = 'auto'
	const h = Math.min(Math.max(el.scrollHeight, 44), AUTOGROW_MAX)
	el.style.height = `${h}px`
	el.style.overflowY = el.scrollHeight > AUTOGROW_MAX ? 'auto' : 'hidden'
}
const vAutogrow = {
	mounted(el) {
		el.addEventListener('input', () => fitTextarea(el))
		nextTick(() => fitTextarea(el))
	},
	updated(el) {
		nextTick(() => fitTextarea(el))
	},
}

// ---- Fetch dokumen ---------------------------------------------------------
const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: DOCTYPE, name: name.value }
	},
	auto: false,
	onSuccess() {
		syncFormFromDoc()
	},
})

// ---- Meta doctype ----------------------------------------------------------
const metaFields = ref([])
const SKIP_TYPES = [
	'Section Break',
	'Column Break',
	'Tab Break',
	'HTML',
	'Button',
	'Heading',
	'Fold',
	'Barcode',
]
// amended_from = housekeeping; workflow_state sudah tampil sebagai pill di header.
const SKIP_FIELDS = ['amended_from', 'workflow_state']

function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text', 'Code', 'Text Editor'].includes(ft)
}
function isNumberField(ft) {
	return ['Int', 'Float', 'Currency', 'Percent'].includes(ft)
}
function selectOptions(field) {
	return String(field.options || '')
		.split('\n')
		.map((s) => s.trim())
		.filter(Boolean)
}

// ---- Editabilitas: mengikuti workflow allow_edit (mirror desk) --------------
// Workflow "Stok Out Motor" (state field: workflow_state):
//   Draft → PIC Tarikan Ops · Request Approval → Manager Ops · sisanya Administrator.
// Submittable: begitu Approved (docstatus 1) / Cancelled (2), dokumen read-only.
const editMode = ref(false)
const wfStateField = ref(null)
const wfEditStates = ref({})
const wfLoaded = ref(false)
async function loadWorkflowEditMap() {
	try {
		const params = new URLSearchParams({ doctype: DOCTYPE })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_workflow_edit_map?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			wfStateField.value = msg.state_field || null
			wfEditStates.value = msg.states || {}
		}
	} catch (e) {
		/* fallback */
	} finally {
		wfLoaded.value = true
	}
}

const readablePermlevels = ref(new Set([0]))
const writablePermlevels = ref(new Set([0]))
const permLoaded = ref(false)
async function loadPermlevelAccess() {
	try {
		const params = new URLSearchParams({ doctype: DOCTYPE })
		const res = await fetch(
			`/api/method/juragan.api.portal.meta.get_permlevel_access?${params.toString()}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (res.ok) {
			const msg = (await res.json()).message || {}
			readablePermlevels.value = new Set(msg.read || [0])
			writablePermlevels.value = new Set(msg.write || [])
		}
	} catch (e) {
		writablePermlevels.value = new Set()
	} finally {
		permLoaded.value = true
	}
}

const canEditDoc = computed(() => {
	if (!wfLoaded.value || !permLoaded.value || !currentUser.rolesLoaded) return false
	if (doc.data?.docstatus !== 0) return false
	if (wfStateField.value) {
		const status = doc.data?.[wfStateField.value]
		if (!status) return true
		const allow = wfEditStates.value[status] || []
		return (currentUser.roles || []).some((r) => allow.includes(r))
	}
	return writablePermlevels.value.has(0)
})

function enterEditMode() {
	if (canEditDoc.value) editMode.value = true
}
function cancelEdit() {
	syncFormFromDoc()
	editMode.value = false
	openDropdown.value = ''
	saveError.value = ''
}
watch(canEditDoc, (can) => {
	if (!can) editMode.value = false
})

// ---- Form editable ---------------------------------------------------------
const form = reactive({})
const saving = ref(false)
const saveError = ref('')

function syncFormFromDoc() {
	Object.assign(form, doc.data || {})
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && form[f.fieldname] != null && form[f.fieldname] !== '') {
			form[f.fieldname] = String(form[f.fieldname])
		}
	}
	resolveAllLinks()
}

const inputClass =
	'min-h-[44px] w-full rounded-md border border-ui-line-gray-300 bg-ui-surface px-3 py-2 text-base text-ui-ink-gray-800 outline-none transition focus:border-primary focus:ring-2 focus:ring-inset focus:ring-primary/30 md:min-h-0'

// ---- Kondisi depends_on / read_only / reqd ---------------------------------
function evalCondition(expr) {
	if (!expr) return true
	try {
		const code = String(expr).replace(/^eval:/, '')
		const in_list = (list, item) => Array.isArray(list) && list.includes(item)
		const cint = (v) => parseInt(v, 10) || 0
		const cstr = (v) => (v == null ? '' : String(v))
		const flt = (v) => parseFloat(v) || 0
		// eslint-disable-next-line no-new-func
		return !!new Function('doc', 'in_list', 'cint', 'cstr', 'flt', `return (${code})`)(
			form,
			in_list,
			cint,
			cstr,
			flt
		)
	} catch (e) {
		return true
	}
}
function isFieldReqd(field) {
	if (field.reqd) return true
	return field.mandatory_depends_on ? evalCondition(field.mandatory_depends_on) : false
}
function isFieldReadOnly(field) {
	if (!editMode.value) return true
	if (field.read_only) return true
	if (!writablePermlevels.value.has(field.permlevel || 0)) return true
	return field.read_only_depends_on ? evalCondition(field.read_only_depends_on) : false
}
function fieldClass(field) {
	return [
		inputClass,
		isFieldReadOnly(field)
			? '!bg-ui-surface-gray-100 !text-ui-ink-gray-500 !border-ui-line-gray-200 cursor-not-allowed'
			: '',
	]
}

// ---- Format nilai ----------------------------------------------------------
function formatCurrency(v) {
	const n = Number(v)
	if (v === '' || v == null || Number.isNaN(n)) return String(v ?? '')
	return new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 2,
		maximumFractionDigits: 2,
	}).format(n)
}
function currencyDisplay(v) {
	if (v === '' || v == null || Number.isNaN(Number(v))) return ''
	return `Rp ${formatCurrency(v)}`
}
function numberDisplay(field, v) {
	if (v == null || v === '') return '—'
	if (field.fieldtype === 'Currency') return currencyDisplay(v) || '—'
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return new Intl.NumberFormat('id-ID').format(n)
}
function formatDateDisplay(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
function parseCurrency(str) {
	if (str == null) return ''
	const cleaned = String(str)
		.replace(/\./g, '')
		.replace(',', '.')
		.replace(/[^\d.]/g, '')
	if (cleaned === '') return ''
	const n = Number(cleaned)
	return Number.isNaN(n) ? '' : n
}
function onCurrencyBlur(field, e) {
	const n = parseCurrency(e.target.value)
	form[field.fieldname] = n
	e.target.value = currencyDisplay(n)
}

// ---- Link searchable + resolusi judul --------------------------------------
const linkTitleField = reactive({})
const linkTitles = reactive({})
const linkOptions = reactive({})

async function loadLinkMeta() {
	const dts = new Set()
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options) dts.add(f.options)
	}
	await Promise.all(
		[...dts].map(async (dt) => {
			try {
				const res = await fetch(
					`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(
						dt
					)}`,
					{
						method: 'GET',
						credentials: 'include',
						headers: { Accept: 'application/json' },
					}
				)
				const json = await res.json()
				const docs = json.docs || json.message?.docs || []
				const meta = docs.find((x) => x.name === dt) || docs[0]
				linkTitleField[dt] = (meta && meta.title_field) || null
			} catch (e) {
				linkTitleField[dt] = null
			}
		})
	)
	resolveAllLinks()
	for (const dt of dts) loadLinkOptions(dt)
}
async function loadLinkOptions(dt) {
	if (linkOptions[dt]) return
	const titleField = linkTitleField[dt]
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const lparams = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '101',
			order_by: 'name asc',
		})
		const lres = await fetch(`/api/method/frappe.client.get_list?${lparams.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const ljson = await lres.json()
		const recs = ljson.message || []
		if (recs.length && recs.length <= 100) {
			linkOptions[dt] = recs.map((r) => ({
				value: String(r.name),
				label: (titleField && r[titleField]) || String(r.name),
			}))
		}
	} catch (e) {
		/* abaikan */
	}
}
async function resolveLinkTitle(dt, value) {
	const key = `${dt}:${value}`
	if (value == null || value === '' || linkTitles[key] !== undefined) return
	const titleField = linkTitleField[dt]
	if (titleField === undefined) return
	if (titleField === null) {
		linkTitles[key] = String(value)
		return
	}
	try {
		const params = new URLSearchParams({
			doctype: dt,
			fieldname: titleField,
			filters: String(value),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const msg = json.message
		const title = msg && typeof msg === 'object' ? msg[titleField] : msg
		linkTitles[key] = title != null && title !== '' ? title : String(value)
	} catch (e) {
		linkTitles[key] = String(value)
	}
}
function resolveAllLinks() {
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Link' && f.options && form[f.fieldname]) {
			resolveLinkTitle(f.options, form[f.fieldname])
		}
	}
}
function linkDisplay(field) {
	const v = form[field.fieldname]
	if (!v) return ''
	const opts = linkOptions[field.options]
	if (opts) {
		const cur = opts.find((o) => String(o.value).toLowerCase() === String(v).toLowerCase())
		if (cur) return cur.label
	}
	const t = linkTitles[`${field.options}:${v}`]
	if (t !== undefined) return t
	if (linkTitleField[field.options] === null) return v
	return '…'
}

const openDropdown = ref('')
const linkSearch = ref('')
const linkResults = ref([])
const linkSearchLoading = ref(false)
function optionMatch(opt, field) {
	const v = form[field.fieldname]
	if (v == null || v === '') return false
	return String(opt.value).toLowerCase() === String(v).toLowerCase()
}
function linkFilters(field) {
	let raw = field.link_filters
	if (!raw) return []
	try {
		if (typeof raw === 'string') raw = JSON.parse(raw)
	} catch (e) {
		return []
	}
	const out = []
	const push = (f, op, v) => {
		if (typeof v === 'string' && /^eval:|^doc\./.test(v)) return
		out.push([f, op, v])
	}
	if (Array.isArray(raw)) {
		for (const c of raw) {
			if (!Array.isArray(c)) continue
			if (c.length === 4) push(c[1], c[2], c[3])
			else if (c.length === 3) push(c[0], c[1], c[2])
		}
	} else if (raw && typeof raw === 'object') {
		for (const [k, v] of Object.entries(raw)) push(k, '=', v)
	}
	return out
}
function toggleLinkDropdown(field) {
	if (openDropdown.value === field.fieldname) {
		openDropdown.value = ''
		return
	}
	openDropdown.value = field.fieldname
	linkSearch.value = ''
	const opts = linkFilters(field).length ? null : linkOptions[field.options]
	if (opts) linkResults.value = opts
	else fetchLinkResults(field, '')
}
async function fetchLinkResults(field, query) {
	const dt = field.options
	const titleField = linkTitleField[dt]
	linkSearchLoading.value = true
	linkResults.value = []
	try {
		const flds = titleField ? ['name', titleField] : ['name']
		const params = new URLSearchParams({
			doctype: dt,
			fields: JSON.stringify(flds),
			limit_page_length: '20',
			order_by: 'name asc',
		})
		const lf = linkFilters(field)
		if (lf.length) params.set('filters', JSON.stringify(lf))
		if (query) {
			const ors = [['name', 'like', `%${query}%`]]
			if (titleField) ors.push([titleField, 'like', `%${query}%`])
			params.set('or_filters', JSON.stringify(ors))
		}
		const res = await fetch(`/api/method/frappe.client.get_list?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		const json = await res.json()
		const recs = json.message || []
		linkResults.value = recs.map((r) => ({
			value: String(r.name),
			label: (titleField && r[titleField]) || String(r.name),
		}))
	} catch (e) {
		linkResults.value = []
	} finally {
		linkSearchLoading.value = false
	}
}
let linkSearchTimer = null
function onLinkSearch(field) {
	const q = linkSearch.value.trim()
	const opts = linkFilters(field).length ? null : linkOptions[field.options]
	if (opts) {
		const ql = q.toLowerCase()
		linkResults.value = ql
			? opts.filter(
					(o) =>
						o.label.toLowerCase().includes(ql) ||
						String(o.value).toLowerCase().includes(ql)
			  )
			: opts
		return
	}
	clearTimeout(linkSearchTimer)
	linkSearchTimer = setTimeout(() => fetchLinkResults(field, q), 300)
}
function selectLink(field, value, label) {
	form[field.fieldname] = value
	if (label != null) linkTitles[`${field.options}:${value}`] = label
	openDropdown.value = ''
	applyFetchFrom(field, value)
}
// Tiru `fetch_from` Frappe (mis. id_dealer → nama_dealer).
async function applyFetchFrom(linkField, value) {
	const prefix = `${linkField.fieldname}.`
	const targets = metaFields.value.filter(
		(f) => typeof f.fetch_from === 'string' && f.fetch_from.startsWith(prefix)
	)
	if (!targets.length) return
	if (!value) {
		for (const t of targets) form[t.fieldname] = null
		return
	}
	const sourceFields = targets.map((t) => t.fetch_from.slice(prefix.length))
	try {
		const params = new URLSearchParams({
			doctype: linkField.options,
			filters: JSON.stringify({ name: value }),
			fieldname: JSON.stringify(sourceFields),
		})
		const res = await fetch(`/api/method/frappe.client.get_value?${params.toString()}`, {
			method: 'GET',
			credentials: 'include',
			headers: { Accept: 'application/json' },
		})
		if (!res.ok) return
		const data = (await res.json())?.message || {}
		for (const t of targets) {
			const src = t.fetch_from.slice(prefix.length)
			if (src in data) form[t.fieldname] = data[src]
		}
	} catch (e) {
		/* abaikan */
	}
}

// ---- Date picker in-app (pengganti <input type=date>) ----------------------
const DP_WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const DP_MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]
const datePicker = reactive({
	open: false,
	fieldname: '',
	label: 'Pilih Tanggal',
	cursor: new Date(),
})
function dpYmd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function dpParse(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}
function openDatePicker(field) {
	if (isFieldReadOnly(field)) return
	datePicker.fieldname = field.fieldname
	datePicker.label = field.label || 'Pilih Tanggal'
	const base = form[field.fieldname] || dpYmd(new Date())
	const d = dpParse(base)
	datePicker.cursor = new Date(d.getFullYear(), d.getMonth(), 1)
	datePicker.open = true
}
const dpLabel = computed(
	() => `${DP_MONTHS[datePicker.cursor.getMonth()]} ${datePicker.cursor.getFullYear()}`
)
const dpDays = computed(() => {
	const year = datePicker.cursor.getFullYear()
	const month = datePicker.cursor.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})
function dpPrevMonth() {
	datePicker.cursor = new Date(
		datePicker.cursor.getFullYear(),
		datePicker.cursor.getMonth() - 1,
		1
	)
}
function dpNextMonth() {
	datePicker.cursor = new Date(
		datePicker.cursor.getFullYear(),
		datePicker.cursor.getMonth() + 1,
		1
	)
}
function dpDayClass(date) {
	const s = dpYmd(date)
	if (s === form[datePicker.fieldname]) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (s === dpYmd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}
function pickDate(date) {
	form[datePicker.fieldname] = dpYmd(date)
	datePicker.open = false
}
function clearDate() {
	if (datePicker.fieldname) form[datePicker.fieldname] = ''
	datePicker.open = false
}

// ---- Susun section dari meta -----------------------------------------------
const sectionsStructure = computed(() => {
	const sections = []
	let curSection = null
	let curCol = null
	const ensureSection = () => {
		if (!curSection) {
			curCol = []
			curSection = { label: '', columns: [curCol] }
			sections.push(curSection)
		}
	}
	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Section Break') {
			curCol = []
			curSection = { label: f.label || '', columns: [curCol] }
			sections.push(curSection)
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) ensureSection()
			else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (SKIP_TYPES.includes(ft) || SKIP_FIELDS.includes(f.fieldname)) continue
		ensureSection()
		curCol.push(f)
	}
	return sections
})

function fieldVisible(f) {
	if (f.hidden) return false
	if (!readablePermlevels.value.has(f.permlevel || 0)) return false
	if (f.depends_on && !evalCondition(f.depends_on)) return false
	return true
}
function hasValue(f) {
	const v = doc.data?.[f.fieldname]
	if (f.fieldtype === 'Check') return !!v
	if (Array.isArray(v)) return v.length > 0
	return !(v == null || (typeof v === 'string' && v.trim() === ''))
}
function hasFormValue(f) {
	const v = form[f.fieldname]
	if (f.fieldtype === 'Check') return !!v
	if (Array.isArray(v)) return v.length > 0
	return !(v == null || (typeof v === 'string' && v.trim() === ''))
}

// Mode baca → hanya field terisi. Mode edit → field yang bisa ditulis, atau
// read-only yang sudah ada isinya.
// Apakah sebuah field ditampilkan (visibilitas + isi + mode edit).
function fieldShown(f) {
	if (!fieldVisible(f)) return false
	if (f.fieldtype === 'Table') {
		// Mode edit + child bisa ditulis → tetap tampil (tombol Tambah Unit)
		// walau masih kosong; selain itu tampil bila ada isi.
		if (editMode.value && !isFieldReadOnly(f)) return true
		return tableRows(f.fieldname).length > 0
	}
	if (editMode.value) return !isFieldReadOnly(f) || hasFormValue(f)
	return hasValue(f)
}

// Field ringkasan (total + catatan) dikumpulkan ke satu kartu "Ringkasan" yang
// ditaruh DI ATAS List Unit, dipisah dari posisi aslinya di meta.
const SUMMARY_FIELDS = ['total_unit', 'total_tagihan', 'catatan']
function fieldByName(fn) {
	return metaFields.value.find((f) => f.fieldname === fn)
}

// Konten dirender sebagai daftar blok berurutan:
//   - { type: 'units', field } → child table List Unit sebagai kartu, TANPA
//     container putih (mengikuti tampilan Request AYDA).
//   - { type: 'fields', label, columns } → field biasa dalam container putih.
const contentBlocks = computed(() => {
	const summarySet = new Set(SUMMARY_FIELDS)
	// Kartu ringkasan: Total Unit, Total Tagihan, Catatan (yang terisi/bisa edit).
	const summaryCol = SUMMARY_FIELDS.map(fieldByName).filter((f) => f && fieldShown(f))
	const summaryBlock = summaryCol.length
		? { type: 'fields', label: 'Ringkasan', columns: [summaryCol] }
		: null
	let summaryInserted = false

	const blocks = []
	for (const sec of sectionsStructure.value) {
		// Child Table → kartu; sisipkan kartu Ringkasan tepat sebelum List Unit.
		for (const f of sec.columns.flat()) {
			if (f.fieldtype === 'Table' && fieldShown(f)) {
				if (summaryBlock && !summaryInserted) {
					blocks.push(summaryBlock)
					summaryInserted = true
				}
				blocks.push({ type: 'units', field: f })
			}
		}
		// Field biasa (non-Table, bukan field ringkasan) → container putih.
		const columns = sec.columns
			.map((col) =>
				col.filter(
					(f) => f.fieldtype !== 'Table' && !summarySet.has(f.fieldname) && fieldShown(f)
				)
			)
			.filter((col) => col.length)
		if (columns.length) blocks.push({ type: 'fields', label: sec.label, columns })
	}
	// Bila tak ada List Unit, tetap tampilkan Ringkasan di paling atas konten.
	if (summaryBlock && !summaryInserted) blocks.unshift(summaryBlock)
	return blocks
})

// ---- Simpan ----------------------------------------------------------------
function frappeError(json) {
	try {
		if (json && json._server_messages) {
			const arr = JSON.parse(json._server_messages)
			return arr
				.map((m) => {
					try {
						return JSON.parse(m).message
					} catch (e) {
						return m
					}
				})
				.join('\n')
		}
	} catch (e) {
		/* ignore */
	}
	return (json && (json.exception || json.message)) || ''
}
async function saveDoc(docObj) {
	const res = await fetch('/api/method/frappe.client.save', {
		method: 'POST',
		credentials: 'include',
		headers: {
			'Content-Type': 'application/json',
			Accept: 'application/json',
			'X-Frappe-CSRF-Token': window.csrf_token || '',
		},
		body: JSON.stringify({ doc: docObj }),
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
	return json.message
}
async function saveDocument() {
	saving.value = true
	saveError.value = ''
	try {
		const payload = JSON.parse(JSON.stringify(form))
		payload.doctype = DOCTYPE
		payload.name = name.value
		await saveDoc(payload)
		await doc.fetch()
		editMode.value = false
		loadTransitions()
		notifySuccess('Perubahan berhasil disimpan.')
	} catch (e) {
		saveError.value = e.message || String(e)
		notifyError(e, 'Gagal menyimpan')
	} finally {
		saving.value = false
	}
}

// ---- Actions workflow (transisi dari Frappe core) --------------------------
const actionsOpen = ref(false)
const transitions = reactive({ loading: false, items: [], applying: '', error: '' })

// Aksi bernuansa destruktif → tombol & modal konfirmasi merah.
const DANGER_ACTIONS = ['cancel', 'reject']
function isDangerAction(action) {
	const a = String(action || '').toLowerCase()
	return DANGER_ACTIONS.some((d) => a.includes(d))
}

// Modal konfirmasi in-app (dialog browser tidak muncul di webview APK).
const confirmDialog = reactive({
	open: false,
	title: '',
	message: '',
	label: 'Ya',
	variant: 'primary',
	onConfirm: null,
})
function askConfirm(opts, onConfirm) {
	confirmDialog.title = opts.title || 'Konfirmasi'
	confirmDialog.message = opts.message || ''
	confirmDialog.label = opts.label || 'Ya'
	confirmDialog.variant = opts.variant || 'primary'
	confirmDialog.onConfirm = onConfirm
	actionsOpen.value = false
	confirmDialog.open = true
}
function confirmYes() {
	const fn = confirmDialog.onConfirm
	confirmDialog.open = false
	confirmDialog.onConfirm = null
	if (typeof fn === 'function') fn()
}
function confirmNo() {
	confirmDialog.open = false
	confirmDialog.onConfirm = null
}
const confirmBtnClass = computed(() => {
	if (confirmDialog.variant === 'danger') return 'bg-red-600 hover:bg-red-700'
	if (confirmDialog.variant === 'success') return 'bg-green-600 hover:bg-green-700'
	return 'bg-primary hover:bg-primary/90'
})
const confirmIconClass = computed(() => {
	if (confirmDialog.variant === 'danger') return 'bg-ui-surface-red-100 text-ui-ink-red-600'
	if (confirmDialog.variant === 'success') return 'bg-ui-surface-green-100 text-ui-ink-green-600'
	return 'bg-primary/10 text-primary'
})

// ---- Modal Alasan Cancel ---------------------------------------------------
// Aksi "Cancel" memicu on_cancel yang MEWAJIBKAN alasan_cancel (server throw bila
// kosong). Field-nya hidden, jadi diminta lewat modal lalu DISIMPAN KE DB dulu —
// persis before_workflow_action desk: apply_workflow memuat ulang dokumen dari DB,
// sehingga nilai in-memory akan terbuang. frappe.client.set_value tidak memicu
// validate/on_submit → aman untuk dokumen submitted.
const cancelReason = reactive({ open: false, value: '', error: '', submitting: false })

function openCancelReason() {
	cancelReason.value = ''
	cancelReason.error = ''
	cancelReason.submitting = false
	actionsOpen.value = false
	cancelReason.open = true
}

async function submitCancelReason() {
	const alasan = String(cancelReason.value || '').trim()
	if (!alasan) {
		cancelReason.error = 'Alasan Cancel wajib diisi.'
		return
	}
	if (cancelReason.submitting) return
	cancelReason.submitting = true
	cancelReason.error = ''
	try {
		// Simpan alasan_cancel ke DB SEBELUM apply_workflow.
		const res = await fetch('/api/method/frappe.client.set_value', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({
				doctype: DOCTYPE,
				name: name.value,
				fieldname: 'alasan_cancel',
				value: alasan,
			}),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		cancelReason.open = false
		await applyAction('Cancel')
	} catch (e) {
		cancelReason.error = e.message || String(e)
	} finally {
		cancelReason.submitting = false
	}
}

// Klik aksi → Cancel minta alasan dulu; aksi lain cukup konfirmasi.
function onActionClick(t) {
	if (String(t.action).trim().toLowerCase() === 'cancel') {
		openCancelReason()
		return
	}
	askConfirm(
		{
			title: `${t.action}?`,
			message: `Terapkan aksi "${t.action}" pada ${displayTitle.value}? Status akan menjadi "${t.next_state}".`,
			label: t.action,
			variant: isDangerAction(t.action) ? 'danger' : 'primary',
		},
		() => applyAction(t.action)
	)
}

async function loadTransitions() {
	if (!doc.data) return
	transitions.loading = true
	try {
		const res = await fetch('/api/method/frappe.model.workflow.get_transitions', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data }),
		})
		const json = await res.json()
		transitions.items = json.message || []
	} catch (e) {
		transitions.items = []
	} finally {
		transitions.loading = false
	}
}
async function applyAction(action) {
	transitions.applying = action
	transitions.error = ''
	try {
		const res = await fetch('/api/method/frappe.model.workflow.apply_workflow', {
			method: 'POST',
			credentials: 'include',
			headers: {
				'Content-Type': 'application/json',
				Accept: 'application/json',
				'X-Frappe-CSRF-Token': window.csrf_token || '',
			},
			body: JSON.stringify({ doc: doc.data, action }),
		})
		const json = await res.json().catch(() => ({}))
		if (!res.ok) throw new Error(frappeError(json) || `HTTP ${res.status}`)
		actionsOpen.value = false
		await doc.fetch()
		loadTransitions()
		notifySuccess(`Aksi "${action}" berhasil diterapkan.`)
	} catch (e) {
		transitions.error = e.message || String(e)
		actionsOpen.value = false
		notifyError(e, `Gagal menerapkan aksi "${action}"`)
	} finally {
		transitions.applying = ''
	}
}

const showBottomBar = computed(
	() => !!doc.data && (editMode.value || transitions.items.length > 0)
)

// ---- Muat meta -------------------------------------------------------------
async function loadMeta() {
	try {
		const res = await fetch(
			`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(DOCTYPE)}`,
			{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
		)
		if (!res.ok) throw new Error(`HTTP ${res.status}`)
		const json = await res.json()
		const docs = json.docs || json.message?.docs || []
		const dt = docs.find((x) => x.name === DOCTYPE) || docs[0]
		metaFields.value = (dt && dt.fields) || []
		syncFormFromDoc()
		loadLinkMeta().catch(() => {})
	} catch (e) {
		/* meta gagal → section tidak terbentuk */
	}
}

onMounted(async () => {
	await refreshCsrfToken()
	loadMyRoles()
	await Promise.all([loadMeta(), loadWorkflowEditMap(), loadPermlevelAccess()])
	doc.fetch().then(() => loadTransitions())
})
